+        return switch (TEST_CASE) {
+            case "success65" -> createSSLContext(
+                    new Cert[] { Cert.CA_RSA_SHA384_FOR_MLDSA },
+                    new Cert[] { Cert.EE_MLDSA_65 },
+                    getClientContextParameters());
+            case "success87" -> createSSLContext(
+                    new Cert[] { Cert.CA_RSA_SHA384_FOR_MLDSA },
+                    new Cert[] { Cert.EE_MLDSA_87 },
+                    getClientContextParameters());
